//! MIDI clock in: DIN tempo tracking, USB clock reports from the SHARC,
//! start/stop, and the DSP clock-enable sequencing of `MidiController`.
//! Clock out is generated by the SHARC (0x25). On QC the ARM side sends one DIN F8
//! per IRQ with `MidiController::transmit(&MidiMessage::Realtime(TimingClock))`.

use std::ops::{Add, Sub};
use std::time::Duration;

use crate::dispatch::MidiAction;
use crate::output::{DspCommand, MidiOutput, SettingReport};
use crate::settings::{ClockOut, MidiSettings};

/// Single-shot DIN clock timeout (`setInterval(200)` @0x330bb4).
pub const DIN_CLOCK_TIMEOUT: Duration = Duration::from_millis(200);
/// Accepted rounded tempo, inclusive (DIN tracker and USB report).
pub const TEMPO_MIN: f32 = 30.0;
pub const TEMPO_MAX: f32 = 260.0;
const TICKS_PER_BEAT: u32 = 24;
/// Rate of the SHARC tick stamp in a DSP `0x26` record (`0x004f1288` divides by 5e8).
const DSP_STAMP_HZ: f32 = 5e8;

/// Tempo source mode read by `0x0064c828` (a rounded 0/1 parameter).
/// Names are inferred: in `Global` mode MIDI clock writes global parameter
/// 0x87; in `Preset` mode it sends 0x16 directly.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum TempoMode {
    #[default]
    Preset,
    Global,
}

/// Tempo state the application owns.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TempoContext {
    pub mode: TempoMode,
    /// The tempo stock restores with 0x16 when external clock stops (`0x0064c6e0`).
    pub current_bpm: i32,
}

impl Default for TempoContext {
    fn default() -> Self {
        Self {
            mode: TempoMode::Preset,
            current_bpm: 120,
        }
    }
}

#[derive(Debug, Clone)]
struct MovingSum<T, const N: usize> {
    values: [T; N],
    len: usize,
    next: usize,
    sum: T,
}

impl<T: Copy + Default + Add<Output = T> + Sub<Output = T>, const N: usize> MovingSum<T, N> {
    fn new() -> Self {
        Self {
            values: [T::default(); N],
            len: 0,
            next: 0,
            sum: T::default(),
        }
    }

    /// Push and return the number of samples now held.
    fn push(&mut self, value: T) -> usize {
        if self.len < N {
            self.len += 1;
        } else {
            self.sum = self.sum - self.values[self.next];
        }
        self.sum = self.sum + value;
        self.values[self.next] = value;
        self.next = (self.next + 1) % N;
        self.len
    }
}

/// DIN clock tempo tracker (`0x004f103c` / `0x004f11d0`): a 48-interval
/// moving average that restarts on a full window and an interval outside
/// 0.7..=1.3 of the average, then a 24-sample moving average of the BPM.
#[derive(Debug, Clone)]
pub struct TempoTracker {
    ticks: u32,
    last: Option<Duration>,
    /// Last SHARC stamp (`+0x18`) of the QC mini tracker `0x004f1288`.
    last_stamp: Option<u32>,
    intervals: MovingSum<f64, 48>,
    bpms: MovingSum<f32, 24>,
    bpm: f32,
}

impl Default for TempoTracker {
    fn default() -> Self {
        Self {
            ticks: 0,
            last: None,
            last_stamp: None,
            intervals: MovingSum::new(),
            bpms: MovingSum::new(),
            bpm: 0.0,
        }
    }
}

impl TempoTracker {
    /// Count one F8 at `now` and return the rounded BPM.
    pub fn tick(&mut self, now: Duration) -> f32 {
        self.ticks = self.ticks.wrapping_add(1);
        if let Some(previous) = self.last.replace(now) {
            let seconds = now.saturating_sub(previous).as_nanos() as f32 / 1e9;
            self.push_interval(seconds);
        }
        (self.bpm + 0.5).floor()
    }

    /// Count one F8 of the QC mini (`0x004f1288`): the interval is the wrapping
    /// difference of the SHARC stamps, at 500 MHz.
    pub fn tick_stamp(&mut self, stamp: u32) -> f32 {
        self.ticks = self.ticks.wrapping_add(1);
        if let Some(previous) = self.last_stamp.replace(stamp) {
            self.push_interval(stamp.wrapping_sub(previous) as f32 / DSP_STAMP_HZ);
        }
        (self.bpm + 0.5).floor()
    }

    fn push_interval(&mut self, seconds: f32) {
        let len = self.intervals.push(f64::from(seconds));
        let average = (self.intervals.sum / len as f64) as f32;
        if (seconds < average * 0.7 || average * 1.3 < seconds) && len == 48 {
            self.intervals = MovingSum::new();
        }
        if average > 0.0 {
            let len = self.bpms.push(60.0 / (average * TICKS_PER_BEAT as f32));
            self.bpm = self.bpms.sum / len as f32;
        }
    }

    pub fn ticks(&self) -> u32 {
        self.ticks
    }
}

fn in_range(bpm: f32) -> bool {
    (TEMPO_MIN..=TEMPO_MAX).contains(&bpm)
}

/// Clock-in state of `MidiController` (fields +0xfc..+0x104, +0x120).
#[derive(Debug, Clone)]
pub struct ClockState {
    tracker: TempoTracker,
    start_latch: bool,
    usb_running: bool,
    din_running: bool,
    out_of_range: Option<f32>,
    /// 120 at boot, 0 after stop/timeout.
    external_tempo: f32,
    /// Time of the last accepted DIN F8; arms the 200 ms timeout.
    last_din_tick: Option<Duration>,
}

impl Default for ClockState {
    fn default() -> Self {
        Self {
            tracker: TempoTracker::default(),
            start_latch: false,
            usb_running: false,
            din_running: false,
            out_of_range: None,
            external_tempo: 120.0,
            last_din_tick: None,
        }
    }
}

/// What a clock step may read and where it writes.
pub(crate) struct ClockEnv<'a> {
    pub settings: &'a MidiSettings,
    pub tempo: TempoContext,
    pub preset_ready: bool,
    pub out: &'a mut Vec<MidiOutput>,
}

impl ClockEnv<'_> {
    fn dsp(&mut self, command: DspCommand) {
        self.out.push(MidiOutput::Dsp(command));
    }

    fn action(&mut self, action: MidiAction) {
        self.out.push(MidiOutput::Action(action));
    }

    fn report(&mut self, report: SettingReport) {
        self.action(MidiAction::Report(report));
    }

    /// 0x16 with the application tempo, sent only in `Preset` mode.
    fn restore_tempo(&mut self) {
        if self.tempo.mode == TempoMode::Preset {
            let bpm = self.tempo.current_bpm;
            self.dsp(DspCommand::TempoChange(bpm));
            self.action(MidiAction::MetronomeTempo(bpm));
        }
    }

    fn clock_in_gate(&self, usb_running: bool) -> bool {
        self.settings.clock_in && self.settings.clock_out == ClockOut::Off && !usb_running
    }
}

impl ClockState {
    pub fn din_running(&self) -> bool {
        self.din_running
    }

    pub fn usb_running(&self) -> bool {
        self.usb_running
    }

    pub fn out_of_range(&self) -> Option<f32> {
        self.out_of_range
    }

    /// 0 after stop or timeout.
    pub fn external_tempo(&self) -> f32 {
        self.external_tempo
    }

    pub fn din_timeout_deadline(&self) -> Option<Duration> {
        self.last_din_tick.map(|tick| tick + DIN_CLOCK_TIMEOUT)
    }

    fn report_internal(&self, env: &mut ClockEnv<'_>) {
        let internal = !self.usb_running && !self.din_running;
        env.report(SettingReport::InternalMidiClockEnabled(internal));
    }

    /// `0x0032f8dc`.
    pub(crate) fn set_din_running(&mut self, env: &mut ClockEnv<'_>, mut running: bool) {
        if env.settings.clock_out == ClockOut::Off {
            if running == self.din_running {
                return;
            }
        } else {
            env.dsp(DspCommand::EnableInternalMidiClock(true));
            running = false;
            if !self.din_running {
                return;
            }
        }
        if !self.usb_running && running {
            self.din_running = true;
            env.dsp(DspCommand::EnableUsbMidiClock(false));
            env.dsp(DspCommand::EnableInternalMidiClock(false));
            env.restore_tempo();
            env.action(MidiAction::ClockRunning(true));
        } else {
            self.din_running = false;
            env.dsp(DspCommand::EnableUsbMidiClock(env.settings.over_usb));
            if !self.usb_running {
                env.dsp(DspCommand::EnableInternalMidiClock(true));
                env.restore_tempo();
                env.action(MidiAction::ClockRunning(false));
            }
        }
        self.report_internal(env);
    }

    /// `0x0032f52c`.
    pub(crate) fn set_usb_running(&mut self, env: &mut ClockEnv<'_>, mut running: bool) {
        if env.settings.clock_out == ClockOut::Off {
            if running == self.usb_running {
                return;
            }
        } else {
            env.dsp(DspCommand::EnableInternalMidiClock(true));
            running = false;
            if !self.usb_running {
                return;
            }
        }
        if self.din_running {
            self.usb_running = false;
        } else {
            self.usb_running = running;
            env.dsp(DspCommand::EnableInternalMidiClock(!running));
            env.restore_tempo();
            env.action(MidiAction::ClockRunning(running));
        }
        self.report_internal(env);
    }

    /// `0x0032fc08`.
    fn apply_tempo(&mut self, env: &mut ClockEnv<'_>, bpm: f32) {
        self.external_tempo = bpm;
        env.dsp(DspCommand::TempoChange(bpm as i32));
        env.action(MidiAction::MetronomeTempo(bpm as i32));
        if env.tempo.mode == TempoMode::Global {
            env.action(MidiAction::GlobalTempo(bpm.round().clamp(40.0, 240.0)));
        }
        if self.din_running || self.usb_running {
            env.report(SettingReport::ExternalMidiClockTempo(bpm));
        }
        env.action(MidiAction::ExternalTempoChanged);
    }

    /// `0x0032fdbc`; BPM values above 259 are stored as 260.
    fn set_out_of_range(&mut self, env: &mut ClockEnv<'_>, flag: bool, bpm: i32) {
        let bpm = if bpm > 259 { 260.0 } else { bpm as f32 };
        let set = match self.out_of_range {
            None if !flag => return,
            Some(current) if current == bpm && flag => return,
            _ => flag,
        };
        if set {
            self.out_of_range = Some(bpm);
            if env.tempo.mode == TempoMode::Global {
                let forced: i32 = if bpm <= 140.0 { 40 } else { 240 };
                env.dsp(DspCommand::TempoChange(forced));
                env.action(MidiAction::GlobalTempo(forced as f32));
                env.action(MidiAction::ExternalTempoChanged);
            }
        } else {
            self.out_of_range = None;
        }
        env.action(MidiAction::ClockRunning(false));
        env.report(SettingReport::ExternalMidiClockOutOfRange(set));
    }

    fn clear_out_of_range(&mut self, env: &mut ClockEnv<'_>) {
        if self.out_of_range.take().is_some() {
            env.action(MidiAction::ClockRunning(false));
            env.report(SettingReport::ExternalMidiClockOutOfRange(false));
        }
    }

    /// One DIN F8 (`onMessageReceived` type 4). `stamp` is the SHARC stamp of a QC mini
    /// F8 (DSP `0x26`); host time `now` times the others and arms the timeout.
    pub(crate) fn din_tick(&mut self, env: &mut ClockEnv<'_>, now: Duration, stamp: Option<u32>) {
        if !env.clock_in_gate(self.usb_running) {
            return;
        }
        let bpm = match stamp {
            Some(stamp) => self.tracker.tick_stamp(stamp),
            None => self.tracker.tick(now),
        };
        self.last_din_tick = Some(now);
        let ticks = self.tracker.ticks();
        if !in_range(bpm) {
            if ticks > 1 {
                self.set_din_running(env, false);
                self.set_out_of_range(env, true, bpm as i32);
                if ticks % TICKS_PER_BEAT == 1 || ticks == 2 {
                    env.action(MidiAction::TempoLedFlash);
                }
            }
            return;
        }
        self.set_din_running(env, true);
        self.clear_out_of_range(env);
        if env.preset_ready {
            if self.external_tempo != bpm {
                self.apply_tempo(env, bpm);
            }
            if ticks % TICKS_PER_BEAT == 1 {
                env.action(MidiAction::TempoLedBeat);
            }
            env.dsp(DspCommand::MidiClockCountAndTempo {
                tempo: bpm,
                count: ticks,
            });
        }
    }

    /// Start (FA) or Continue (FB). A second start without a stop clears the
    /// latch and sends nothing (stock toggle).
    pub(crate) fn start(&mut self, env: &mut ClockEnv<'_>) {
        if !env.clock_in_gate(self.usb_running) {
            return;
        }
        if self.start_latch {
            self.start_latch = false;
        } else {
            self.start_latch = true;
            self.tracker = TempoTracker::default();
            env.dsp(DspCommand::MidiClockStart);
        }
    }

    /// Stop (FC) from DIN.
    pub(crate) fn stop(&mut self, env: &mut ClockEnv<'_>) {
        if !self.start_latch {
            return;
        }
        if env.settings.clock_out == ClockOut::Off && !self.usb_running {
            self.start_latch = false;
        }
        self.clear_out_of_range(env);
        env.dsp(DspCommand::TempoChange(env.tempo.current_bpm));
        self.external_tempo = 0.0;
    }

    /// Song position pointer: stock sets the tick count to `lsb | msb * 768`.
    pub(crate) fn song_position(&mut self, env: &ClockEnv<'_>, beats: u16) {
        if env.settings.clock_in && env.settings.clock_out == ClockOut::Off {
            self.tracker.ticks = u32::from(beats & 0x7f) | (u32::from(beats >> 7) * 0x300);
        }
    }

    /// `DinMidiClockTimeoutSlot` (`0x0032fb20`), 200 ms after the last tick.
    pub(crate) fn din_timeout(&mut self, env: &mut ClockEnv<'_>) {
        self.last_din_tick = None;
        self.set_din_running(env, false);
        self.clear_out_of_range(env);
        env.dsp(DspCommand::TempoChange(env.tempo.current_bpm));
        self.external_tempo = 0.0;
        self.tracker = TempoTracker::default();
    }

    /// DSP response 0x0e, USB clock tempo (`0x0089b8dc`).
    pub(crate) fn usb_tempo(&mut self, env: &mut ClockEnv<'_>, bpm: i32, count: u32) {
        if !env.settings.over_usb || !env.preset_ready {
            return;
        }
        if (30..=260).contains(&bpm) {
            self.set_usb_running(env, true);
            self.set_out_of_range(env, false, 0);
        } else if count > 1 {
            self.set_usb_running(env, false);
            env.action(MidiAction::TempoLedFlash);
            self.set_out_of_range(env, true, bpm);
        }
        if self.usb_running {
            env.dsp(DspCommand::TempoChange(bpm));
            self.apply_tempo(env, bpm as f32);
        }
    }

    /// DSP response 0x0f or a USB Stop: the USB clock stopped.
    pub(crate) fn usb_stop(&mut self, env: &mut ClockEnv<'_>) {
        self.set_usb_running(env, false);
        self.set_out_of_range(env, false, 0);
        env.dsp(DspCommand::TempoChange(env.tempo.current_bpm));
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A steady 24 PPQN stream at 120 BPM converges to 120 and stays there.
    #[test]
    fn tracker_follows_steady_clock() {
        let mut tracker = TempoTracker::default();
        let period = Duration::from_nanos(500_000_000 / 24);
        let bpm = (0..100).map(|i| tracker.tick(period * i)).last();
        assert_eq!(bpm, Some(120.0));
    }

    /// QC mini F8 timing (`0x004f1288`): 500 MHz SHARC stamps, wrapping u32
    /// difference. 120 BPM is 10 416 667 stamps per tick, across the wrap.
    #[test]
    fn mini_tracker_uses_wrapping_sharc_stamps() {
        let mut tracker = TempoTracker::default();
        let start = u32::MAX - 1_000_000_000;
        let bpm = (0..100u32)
            .map(|i| tracker.tick_stamp(start.wrapping_add(i * 10_416_667)))
            .last();
        assert_eq!(bpm, Some(120.0));
    }

    /// A full window drops its history when one interval is far off.
    #[test]
    fn tracker_restarts_on_outlier() {
        let mut tracker = TempoTracker::default();
        let period = Duration::from_millis(20);
        for i in 0..49 {
            tracker.tick(period * i);
        }
        assert_eq!(tracker.intervals.len, 48);
        tracker.tick(period * 48 + Duration::from_millis(100));
        assert_eq!(tracker.intervals.len, 0);
    }
}
